// Museum Cards: corpus-driven word maps generated by scripts/wordmap.ts.
// Loaded at build time only (never shipped to the client except through page payloads).
import { readFileSync, readdirSync } from "node:fs";
import { repoPath } from "./paths";

export interface WordRef { s: number; a: number; t: string }
export interface WordForm { form: string; count: number; refs: WordRef[] }
export interface WordColloc { after: string; phrase: string; count: number; refs: WordRef[] }
export interface WordMapFile {
  slug: string; word: string;
  title: { ar: string; en: string };
  total: number;
  forms: WordForm[];
  collocations: WordColloc[];
  corpus: string;
}

const dir = () => repoPath("cards/wordmap");

/** All available word maps, sorted by slug. */
export function listWordMaps(): { slug: string; word: string }[] {
  return readdirSync(dir())
    .filter((f) => f.endsWith(".json") && f !== "index.json")
    .map((f) => {
      const raw = JSON.parse(readFileSync(`${dir()}/${f}`, "utf8")) as WordMapFile;
      return { slug: raw.slug, word: raw.word };
    })
    .sort((a, b) => a.slug.localeCompare(b.slug));
}

const cache = new Map<string, WordMapFile>();
export function loadWordMap(slug: string): WordMapFile {
  const hit = cache.get(slug);
  if (hit) return hit;
  const raw = JSON.parse(readFileSync(`${dir()}/${slug}.json`, "utf8")) as WordMapFile;
  if (raw.slug !== slug) throw new Error(`wordmap: slug mismatch in ${slug}.json`);
  if (raw.total <= 0 || raw.forms.length === 0) throw new Error(`wordmap/${slug}: empty map`);
  cache.set(slug, raw);
  return raw;
}
